    """Tuned Best Fit (lo=7, hi=32, penalty=55): the tightest bin wins, but leaving a gap
    strictly between 7 and 32 units costs 55. lo=0, hi=0, penalty=0 is plain Best Fit."""
    r = bins - item                                  # space left in each bin after placing the item
    return -r - 55 * ((r > 7) & (r < 32))

